	/** 被动技能"法力虹吸"的 Niagara 组件 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UPassiveNiagaraComponent> ManaSiphonNiagaraComponent;

	/** 所有被动特效 Niagara 组件的挂载根节点 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<USceneComponent> EffectAttachComponent;
};
