	/** 获取伤害委托引用（纯虚函数，子类必须实现） */
	virtual FOnDamageSignature& GetOnDamageSignature() = 0;

	/**
	 * 判断角色是否已死亡（蓝图原生事件，蓝图可调用）
	 * @return true 表示角色已死亡
	 */
	UFUNCTION(BlueprintNativeEvent, BlueprintCallable)

```

"}

