/**
 * 游戏开始时初始化
 * 
 * 实现流程：
 * 1. 调用父类 BeginPlay
 * 2. 绑定盒子重叠事件（OnBoxOverlap）
 */
void AAuraEnemySpawnVolume::BeginPlay()
{
	Super::BeginPlay();
	Box->OnComponentBeginOverlap.AddDynamic(this, &AAuraEnemySpawnVolume::OnBoxOverlap);
}

/**
 * 盒子重叠事件处理（玩家进入生成区域）
 * 
 * 实现流程：
 * 1. 检查目标是否实现了 PlayerInterface
 * 2. 设置 bReached = true（标记区域已触发）
