#pragma once

#include "CoreMinimal.h"
#include "Engine/AssetManager.h"
#include "Engine/StreamableManager.h"
#include "AuraAssetManager.generated.h"

struct FVisualEffectConfig;
class UAbilityConfigData;

/**
 * Aura 资产管理器
 *
 * 继承自 UAssetManager，在游戏启动时执行初始化工作
 * 在 DefaultEngine.ini 中配置为项目的 AssetManagerClassName
 *
 * 主要职责：
 * - 重写 StartInitialLoading，初始化原生 GameplayTag 与 GAS 全局数据
 * - 提供软引用资产的异步预加载入口（FStreamableManager）
 * - 避免业务代码中频繁调用 LoadSynchronous() 导致游戏线程阻塞
 *
 * 配置方式（DefaultEngine.ini）：
 * [/Script/Engine.Engine]
 * AssetManagerClassName=/Script/AuraCore.AuraAssetManager
 */
UCLASS()
class AURACORE_API UAuraAssetManager : public UAssetManager
{
	GENERATED_BODY()
public:
	/**
	 * 获取 AssetManager 单例（静态方法）
	 * 内部使用 checkf 校验 AssetManager 类型，配置错误时给出明确报错
	 * @return UAuraAssetManager 实例引用
	 */
	static UAuraAssetManager& Get();

	/**
	 * 异步预加载一组软引用资产
	 * 推荐在技能授予 / 关卡加载完成等"非性能敏感时机"调用
	 * 加载完成后资产会被 StreamableManager 持有，业务侧使用 .Get() 即可拿到指针
	 *
	 * @param SoftPaths 要预加载的资产软路径列表（空数组直接返回）
	 * @param OnComplete 加载完成回调（可选，默认空）
	 * @return 加载句柄，可用于取消或查询进度（无任务时返回 nullptr）
	 */
	TSharedPtr<FStreamableHandle> PreloadAssets(
		const TArray<FSoftObjectPath>& SoftPaths,
		FStreamableDelegate OnComplete = FStreamableDelegate());

	/**
	 * 便捷方法：预加载一个 FVisualEffectConfig 包含的软引用资产（粒子 + 音效）
	 * @param VisualConfig 视觉效果配置
	 * @param OutPaths [out] 收集到的软路径会追加到该数组（用于批量合并加载）
	 */
	static void CollectVisualEffectAssets(
		const FVisualEffectConfig& VisualConfig,
		TArray<FSoftObjectPath>& OutPaths);

	/**
	 * 便捷方法：收集 UAbilityConfigData 中所有需要预加载的软引用资产
	 * 包括 CastVisualEffect、ImpactVisualEffect 以及每个 Action 的 VisualEffect
	 * @param Config 技能配置数据资产（nullptr 时直接返回）
	 * @param OutPaths [out] 收集到的软路径会追加到该数组
	 */
	static void CollectAbilityConfigAssets(
		const UAbilityConfigData* Config,
		TArray<FSoftObjectPath>& OutPaths);

	/** 全局 StreamableManager，用于异步加载软引用资产并持有引用计数 */
	FStreamableManager StreamableManager;

protected:
	/**
	 * 初始加载完成回调（重写基类）
	 * 在引擎完成初始资产加载后调用，注册原生 GameplayTag 与 GAS Target Data
	 */
	virtual void StartInitialLoading() override;
};
