 * 技能授予回调（重写基类）
 *
 * 责任：委托配置数据资产预加载自身需要的软引用资产
 * 业务代码不再感知 FSoftObjectPath / FStreamableManager / UAuraAssetManager
 * 加载策略完全封装在 UAbilityConfigData 内部
 */
void UConfigurableAbility::OnGiveAbility(
	const FGameplayAbilityActorInfo* ActorInfo,
	const FGameplayAbilitySpec& Spec)
{
	Super::OnGiveAbility(ActorInfo, Spec);

	if (AbilityConfig)
	{
		// 委托数据资产自己完成预加载（内部调用 UAuraAssetManager）
		AbilityConfig->PreloadVisualAssets();
	}
}","old_string":"/**
 * 技能授予回调（重写基类）
 *
 * 实现流程：
 * 1. 调用父类 OnGiveAbility
 * 2. 校验 AbilityConfig 已配置
 * 3. 收集所有视觉效果（CastVisualEffect、ImpactVisualEffect、各 Action.VisualEffect）
 * 所引用的软资产路径（粒子系统、音效）
 * 4. 通过 UAuraAssetManager 发起异步加载，避免技能首次激活时 LoadSynchronous 卡顿
 *
 * 注意：
 * - 资产加载完成后由 StreamableManager 持有引用，业务侧 .Get() 即可获得指针
 * - 异步加载失败不会阻塞技能流程，PlayVisualEffect 内有同步加载兜底
 */
void UConfigurableAbility::OnGiveAbility(
	const FGameplayAbilityActorInfo* ActorInfo,
	const FGameplayAbilitySpec& Spec)
{
	Super::OnGiveAbility(ActorInfo, Spec);

	if (!AbilityConfig) return;

	// 收集所有需要预加载的软引用资产路径
	TArray<FSoftObjectPath> Paths;

	auto CollectVisual = [&Paths](const FVisualEffectConfig& VFX)
	{
		if (!VFX.ParticleSystem.IsNull())
		{
			Paths.AddUnique(VFX.ParticleSystem.ToSoftObjectPath());
		}
		if (!VFX.Sound.IsNull())
		{
			Paths.AddUnique(VFX.Sound.ToSoftObjectPath());
		}
	};

	CollectVisual(AbilityConfig->CastVisualEffect);
	CollectVisual(AbilityConfig->ImpactVisualEffect);
	for (const FAbilityActionConfig& Action : AbilityConfig->Actions)
	{
		CollectVisual(Action.VisualEffect);
	}

	// 异步预加载（无任务时内部会直接返回）
	UAuraAssetManager::Get().PreloadAssets(Paths);
}"},{"new_string":"	// 播放施法视觉效果（有任何资产即触发）
	if (AbilityConfig->CastVisualEffect.HasAnyAsset())
	{","old_string":"	// 播放施法视觉效果（路径已配置即触发；资产是否加载完成由 PlayVisualEffect 判断）
	if (!AbilityConfig->CastVisualEffect.ParticleSystem.IsNull() ||
		!AbilityConfig->CastVisualEffect.Sound.IsNull())
	{"},{"new_string":"	// 播放视觉效果（有任何资产即触发）
	if (ActionConfig.VisualEffect.HasAnyAsset())
	{","old_string":"	// 播放视觉效果（路径已配置即触发；资产是否加载完成由 PlayVisualEffect 判断）
	if (!ActionConfig.VisualEffect.ParticleSystem.IsNull() ||
		!ActionConfig.VisualEffect.Sound.IsNull())
	{"},{"new_string":"void UConfigurableAbility::PlayVisualEffect(const FVisualEffectConfig& VisualConfig, const FVector& Location, const FRotator& Rotation)
{
	// 播放粒子效果：委托配置结构体自身返回安全指针
	// 业务代码无需关心 “是否已加载 / 如何同步加载兜底” 之类加载策略细节
	if (UNiagaraSystem* ParticleSystem = VisualConfig.GetParticleSystemSafe())
	{
		const FVector SpawnLocation = Location + VisualConfig.LocationOffset;
		const FRotator SpawnRotation = Rotation + VisualConfig.RotationOffset;

		// TODO: bAttachToCharacter 仅需在需要附加逻辑实现后区分处理
		UNiagaraFunctionLibrary::SpawnSystemAtLocation(
			GetWorld(),
			ParticleSystem,
			SpawnLocation,
			SpawnRotation,
			VisualConfig.Scale);
	}

	// 播放音效：同样委托配置结构体自身获取指针
	if (USoundBase* Sound = VisualConfig.GetSoundSafe())
	{
		UGameplayStatics::PlaySoundAtLocation(
			GetWorld(),
			Sound,
			Location + VisualConfig.LocationOffset);
	}
}","old_string":"void UConfigurableAbility::PlayVisualEffect(const FVisualEffectConfig& VisualConfig, const FVector& Location, const FRotator& Rotation)
{
	// 播放粒子效果
	// 优先使用已缓存的资产（OnGiveAbility 阶段已异步预加载），
	// 仅在异步加载尚未完成时才回退到 LoadSynchronous，避免阻塞游戏线程
	if (!VisualConfig.ParticleSystem.IsNull())
	{
		UNiagaraSystem* ParticleSystem = VisualConfig.ParticleSystem.Get();
		if (!ParticleSystem)
		{
			ParticleSystem = VisualConfig.ParticleSystem.LoadSynchronous();
		}
		if (ParticleSystem)
		{
			FVector SpawnLocation = Location + VisualConfig.LocationOffset;
			FRotator SpawnRotation = Rotation + VisualConfig.RotationOffset;

			if (VisualConfig.bAttachToCharacter)
			{
				// TODO: 实现附加到角色的逻辑
				UNiagaraFunctionLibrary::SpawnSystemAtLocation(
					GetWorld(),
					ParticleSystem,
					SpawnLocation,
					SpawnRotation,
					VisualConfig.Scale);
			}
			else
			{
				UNiagaraFunctionLibrary::SpawnSystemAtLocation(
					GetWorld(),
					ParticleSystem,
					SpawnLocation,
					SpawnRotation,
					VisualConfig.Scale);
			}
		}
	}

	// 播放音效（同样优先使用已缓存资产，未加载时兜底同步加载）
	if (!VisualConfig.Sound.IsNull())
	{
		USoundBase* Sound = VisualConfig.Sound.Get();
		if (!Sound)
		{
			Sound = VisualConfig.Sound.LoadSynchronous();
		}
		if (Sound)
		{
			UGameplayStatics::PlaySoundAtLocation(
				GetWorld(),
				Sound,
				Location + VisualConfig.LocationOffset);
		}
	}
}"}],"apply_mode":"apply_only"}},"timestamp":1780799331,"type":"TOOL_CALL_ARGS"}

