{"rawEvent":{"message_id":"019e9fecd7f173e1a9d4ff5a3578dffd","conversation_id":"019cec84512077ba9b201d16c8fe025f","tool_call_id":"tooluse_L4Nfe8T3urYqnbaUISSlti","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/AuraAttributeSet.cpp","sub_content":"AuraAttributeSet.cpp","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/AuraAttributeSet.cpp","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/AuraAttributeSet.cpp","multi_replace_content":[{"new_string":"#include "AbilitySystem/AuraAttributeSet.h"

#include "AbilitySystemBlueprintLibrary.h"
