{"rawEvent":{"message_id":"019ea01460a97e82b9345ee106b3e310","conversation_id":"019cec84512077ba9b201d16c8fe025f","tool_call_id":"tooluse_yPvSKjK1qBDKkSwkS8Zfwx","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraDamageGameplayAbility.h","sub_content":"AuraDamageGameplayAbility.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraDamageGameplayAbility.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraDamageGameplayAbility.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "AuraAbilityTypes.h"
#include "AbilitySystem/Abilities/AuraGameplayAbility.h"
#include "Interaction/CombatInterface.h"
#include "ScalableFloat.h"
#include "AuraDamageGameplayAbility.generated.h"

/**
 * 伤害基础参数（伤害 GE / 伤害类型 / 基础伤害曲线）
 *
 * 所有伤害型技能必填的核心字段聚合
 */
USTRUCT(BlueprintType)
struct FAuraDamageBase
{
	GENERATED_BODY()

	/**
	 * 伤害 GameplayEffect 类
	 * 此 GE 会触发 ExecCalc_Damage 计算最终伤害并写入 IncomingDamage 元属性
	 * 通常为 GE_Damage
	 */
	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly)
	TSubclassOf<UGameplayEffect> DamageEffectClass;

	/**
	 * 伤害类型标签（火焰/闪电/奥术/物理）
	 * 决定使用哪种抗性属性来减伤，以及触发哪种 Debuff
	 */
	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly)
	FGameplayTag DamageType;

	/**
	 * 基础伤害值（ScalableFloat，支持按等级缩放）
