{"rawEvent":{"message_id":"019ec44ab80c7f6f876fd7d217d7643d","conversation_id":"019cec84512077ba9b201d16c8fe025f","tool_call_id":"tooluse_adLSWznEsitwMVdZW1e5n0","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/Data/AbilityConfigData.cpp","sub_content":"AbilityConfigData.cpp","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/Data/AbilityConfigData.cpp","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/AbilitySystem/Data/AbilityConfigData.cpp","old_string":"void UAbilityConfigData::PreloadVisualAssets() const
{
	// 收集所有视觉效果的软引用路径
	TArray<FSoftObjectPath> Paths;
	CollectVisualSoftPaths(Paths);

	// 委托给 UAuraAssetManager 异步预加载
	// 业务代码 / 调用方完全不感知 FStreamableManager / FSoftObjectPath
	UAuraAssetManager::Get().PreloadAssets(Paths);
}","new_string":"void UAbilityConfigData::PreloadVisualAssets() const
{
	// 构造加载请求：路径 + 分组键（用数据资产名，让生命周期跟随本资产）
	FAuraLoadRequest Request;
	CollectVisualSoftPaths(Request.SoftPaths);
	if (Request.SoftPaths.Num() == 0)
	{
		return;
	}
	Request.GroupKey = FName(*GetName());
	Request.DebugContext = GetName();

	// 提交到 UAuraAssetManager；失败时由 Manager 内部打 Warning 日志
	// 这里再额外感知一次失败结果，方便后续做"降级 / 占位资源"等业务策略
	UAuraAssetManager::Get().SubmitLoadRequest(
		Request,
		FAuraLoadCompleted::CreateLambda([AssetName = GetName()](const FAuraLoadResult& Result)
		{
			if (!Result.bSuccess)
			{
				UE_LOG(LogTemp, Warning,
					TEXT("[AbilityConfig:%s] 视觉资源预加载未全部成功 (%d/%d)"),
					*AssetName, Result.LoadedCount, Result.RequestedCount);
			}
		}));
}","apply_mode":"apply_only"}},"timestamp":1781409801,"type":"TOOL_CALL_ARGS"}

