// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "MVVMViewModelBase.h"
#include "MVVM_LoadScreen.generated.h"

/** 存档槽被选中时广播（通知 UI 更新选中状态） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FSlotSelected);

class UMVVM_LoadSlot;

/**
 * 加载界面 ViewModel
 *
 * 管理整个加载界面的状态和交互逻辑，包含三个存档槽的 ViewModel
 *
 * 职责：
 * - 初始化三个存档槽 ViewModel（LoadSlot_0/1/2）
 * - 从磁盘加载存档数据并更新各槽位的显示状态
 * - 处理玩家的存档槽操作（新建、选择、删除、开始游戏）
 * - 通过 MVVM FieldNotify 机制驱动 UI 更新
 *
 * 存档槽操作流程：
 *   新建游戏：NewSlotButtonPressed → 输入名称 → NewGameButtonPressed → 保存并进入游戏
 *   继续游戏：SelectSlotButtonPressed → PlayButtonPressed → 加载存档进入游戏
 *   删除存档：SelectSlotButtonPressed → DeleteButtonPressed → 删除存档文件
 *
 * MVVM 说明：
 * - NumLoadSlots 使用 FieldNotify，UI 可自动响应数量变化
 * - LoadSlots 映射表通过 GetLoadSlotViewModelByIndex 供 Widget 访问
 */
UCLASS()
class AURA_API UMVVM_LoadScreen : public UMVVMViewModelBase
{
	GENERATED_BODY()
public:

	/**
	 * 初始化所有存档槽 ViewModel
	 * 创建三个 UMVVM_LoadSlot 实例，从磁盘加载存档数据并初始化各槽位状态
	 * 在加载界面 Widget 初始化时调用
	 */
	void InitializeLoadSlots();

	/**
	 * 存档槽被选中时广播
	 * Widget 绑定此委托以响应槽位选中事件（如高亮选中槽位、启用操作按钮）
	 */
	UPROPERTY(BlueprintAssignable)
	FSlotSelected SlotSelected;

	/**
	 * 存档槽 ViewModel 类（在 Details 面板中指定）
	 * 用于创建 LoadSlot_0/1/2 实例
	 */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<UMVVM_LoadSlot> LoadSlotViewModelClass;

	/**
	 * 根据索引获取存档槽 ViewModel（蓝图纯函数）
	 * @param Index 存档槽索引（0、1、2）
	 * @return 对应的 UMVVM_LoadSlot 实例
	 */
	UFUNCTION(BlueprintPure)
	UMVVM_LoadSlot* GetLoadSlotViewModelByIndex(int32 Index) const;

	/**
	 * 新建存档槽按钮按下（蓝图可调用）
	 * 将指定槽位状态设为 EnterName，显示名称输入框
	 * @param Slot        存档槽索引
	 * @param EnteredName 玩家输入的角色名称
	 */
	UFUNCTION(BlueprintCallable)
	void NewSlotButtonPressed(int32 Slot, const FString& EnteredName);

	/**
	 * 确认新建游戏按钮按下（蓝图可调用）
	 * 将槽位状态设为 Taken，保存存档，切换到默认地图
	 * @param Slot 存档槽索引
	 */
	UFUNCTION(BlueprintCallable)
	void NewGameButtonPressed(int32 Slot);

	/**
	 * 选择存档槽按钮按下（蓝图可调用）
	 * 记录当前选中的槽位，广播 SlotSelected 委托，启用操作按钮
	 * @param Slot 存档槽索引
	 */
	UFUNCTION(BlueprintCallable)
	void SelectSlotButtonPressed(int32 Slot);

	/**
	 * 删除存档按钮按下（蓝图可调用）
	 * 删除当前选中槽位的存档文件，将槽位状态重置为 Vacant
	 */
	UFUNCTION(BlueprintCallable)
	void DeleteButtonPressed();

	/**
	 * 开始游戏按钮按下（蓝图可调用）
	 * 加载当前选中槽位的存档，切换到对应地图
	 */
	UFUNCTION(BlueprintCallable)
	void PlayButtonPressed();

	/**
	 * 从磁盘加载所有存档槽数据
	 * 遍历三个槽位，读取存档文件并更新对应 ViewModel 的状态
	 */
	void LoadData();

	/**
	 * 设置存档槽数量（触发 FieldNotify 通知 UI）
	 * @param InNumLoadSlots 存档槽数量（固定为 3）
	 */
	void SetNumLoadSlots(int32 InNumLoadSlots);

	/** 获取存档槽数量 */
	int32 GetNumLoadSlots() const { return NumLoadSlots; }

private:
	/**
	 * 存档槽 ViewModel 映射表
	 * Key: 槽位索引（0、1、2）
	 * Value: 对应的 UMVVM_LoadSlot 实例
	 */
	UPROPERTY()
	TMap<int32, UMVVM_LoadSlot*> LoadSlots;

	/** 第 0 号存档槽 ViewModel */
	UPROPERTY()
	TObjectPtr<UMVVM_LoadSlot> LoadSlot_0;

	/** 第 1 号存档槽 ViewModel */
	UPROPERTY()
	TObjectPtr<UMVVM_LoadSlot> LoadSlot_1;

	/** 第 2 号存档槽 ViewModel */
	UPROPERTY()
	TObjectPtr<UMVVM_LoadSlot> LoadSlot_2;

	/** 当前选中的存档槽 ViewModel（由 SelectSlotButtonPressed 设置） */
	UPROPERTY()
	UMVVM_LoadSlot* SelectedSlot;

	/**
	 * 存档槽数量（支持 MVVM FieldNotify，UI 可自动响应变化）
	 * 固定为 3，但通过 FieldNotify 机制通知 UI 初始化
	 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, FieldNotify, Setter, Getter, meta = (AllowPrivateAccess="true"));
	int32 NumLoadSlots;
};

// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/PlayerController.h"
#include "GameplayTagContainer.h"
#include "AuraPlayerController.generated.h"

class IHighlightInterface;
class UNiagaraSystem;
class UDamageTextComponent;
class UInputMappingContext;
class UInputAction;
struct FInputActionValue;
class UAuraInputConfig;
class UAuraAbilitySystemComponent;
class USplineComponent;
class AMagicCircle;

/**
 * 鼠标目标状态枚举
 * 用于区分当前鼠标光标下的目标类型，影响自动寻路和技能释放行为
 */
enum class ETargetingStatus : uint8
{
	TargetingEnemy,     // 鼠标悬停在敌人上（显示攻击光标，点击触发攻击）
	TargetingNonEnemy,  // 鼠标悬停在非敌人可交互对象上
	NotTargeting        // 鼠标悬停在地面或无效目标上（点击触发自动寻路移动）
};

/**
 * Aura 玩家控制器
 *
 * 职责：
 * - 处理玩家输入（移动、技能释放、Shift 键）
 * - 管理鼠标光标追踪（CursorTrace）和目标高亮
 * - 实现点击移动的自动寻路（基于 Spline 路径）
 * - 管理魔法圆圈的显示/隐藏（用于需要指定位置的技能）
 * - 通过 Client RPC 显示浮动伤害数字
 *
 * 输入流程：
 *   鼠标点击 → AbilityInputTagPressed → ASC.AbilityInputTagPressed
 *   持续按住 → AbilityInputTagHeld → ASC.AbilityInputTagHeld（或触发自动寻路）
 *   释放按键 → AbilityInputTagReleased → ASC.AbilityInputTagReleased
 */
UCLASS()
class AURA_API AAuraPlayerController : public APlayerController
{
	GENERATED_BODY()
public:
	AAuraPlayerController();

	/** 每帧更新：执行光标追踪、自动寻路移动、魔法圆圈位置更新 */
	virtual void PlayerTick(float DeltaTime) override;

	/**
	 * 客户端 RPC：在目标角色位置显示浮动伤害数字
	 * 由服务端调用，在本地客户端生成 DamageTextComponent
	 * @param DamageAmount    伤害数值
	 * @param TargetCharacter 受伤角色（用于确定显示位置）
	 * @param bBlockedHit     是否为格挡命中（显示不同颜色/样式）
	 * @param bCriticalHit    是否为暴击（显示不同颜色/样式）
	 */
	UFUNCTION(Client, Reliable)
	void ShowDamageNumber(float DamageAmount, ACharacter* TargetCharacter, bool bBlockedHit, bool bCriticalHit);

	/**
	 * 在地面显示魔法圆圈（蓝图可调用）
	 * 生成 MagicCircle Actor 并跟随鼠标位置移动
	 * @param DecalMaterial 圆圈贴花材质（nullptr 使用默认材质）
	 */
	UFUNCTION(BlueprintCallable)
	void ShowMagicCircle(UMaterialInterface* DecalMaterial = nullptr);

	/** 隐藏并销毁魔法圆圈（蓝图可调用） */
	UFUNCTION(BlueprintCallable)
	void HideMagicCircle();

protected:
	virtual void BeginPlay() override;

	/** 设置输入组件：绑定移动、Shift 键和技能输入 */
	virtual void SetupInputComponent() override;

private:
	/**
	 * 增强输入映射上下文
	 * 包含所有 Aura 游戏的输入映射（移动、技能等）
	 */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputMappingContext> AuraContext;

	/** 移动输入动作（WASD 或鼠标点击移动） */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputAction> MoveAction;

	/** Shift 键输入动作（按住 Shift 时强制移动而不攻击） */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputAction> ShiftAction;

	/** Shift 键按下回调 */
	void ShiftPressed() { bShiftKeyDown = true; };

	/** Shift 键释放回调 */
	void ShiftReleased() { bShiftKeyDown = false; };

	/** Shift 键当前是否按下（影响点击行为：按住 Shift 时只移动不攻击） */
	bool bShiftKeyDown = false;

	/**
	 * 处理移动输入
	 * @param InputActionValue 包含移动方向的输入值（2D 轴）
	 */
	void Move(const FInputActionValue& InputActionValue);

	/**
	 * 每帧执行鼠标光标追踪
	 * 通过射线检测确定鼠标下方的 Actor，并更新高亮状态和 TargetingStatus
	 */
	void CursorTrace();

	/** 上一帧鼠标悬停的 Actor（用于取消高亮） */
	TObjectPtr<AActor> LastActor;

	/** 当前帧鼠标悬停的 Actor */
	TObjectPtr<AActor> ThisActor;

	/** 鼠标光标射线检测结果（包含命中位置、法线等信息） */
	FHitResult CursorHit;

	/**
	 * 高亮指定 Actor（调用 IHighlightInterface::HighlightActor）
	 * @param InActor 要高亮的 Actor
	 */
	static void HighlightActor(AActor* InActor);

	/**
	 * 取消高亮指定 Actor（调用 IHighlightInterface::UnHighlightActor）
	 * @param InActor 要取消高亮的 Actor
	 */
	static void UnHighlightActor(AActor* InActor);

	/**
	 * 技能输入按下回调（由 AuraInputComponent 绑定）
	 * @param InputTag 按下的输入标签
	 */
	void AbilityInputTagPressed(FGameplayTag InputTag);

	/**
	 * 技能输入释放回调
	 * @param InputTag 释放的输入标签
	 */
	void AbilityInputTagReleased(FGameplayTag InputTag);

	/**
	 * 技能输入持续按住回调
	 * @param InputTag 持续按住的输入标签
	 */
	void AbilityInputTagHeld(FGameplayTag InputTag);

	/**
	 * 技能输入配置数据资产
	 * 定义每个 InputAction 对应的 GameplayTag（如 LMB → InputTag.LMB）
	 */
	UPROPERTY(EditDefaultsOnly, Category="Input")
	TObjectPtr<UAuraInputConfig> InputConfig;

	/** 缓存的 ASC 引用（避免每帧重复查找） */
	UPROPERTY()
	TObjectPtr<UAuraAbilitySystemComponent> AuraAbilitySystemComponent;

	/** 懒加载获取 ASC（首次调用时从 PlayerState 获取并缓存） */
	UAuraAbilitySystemComponent* GetASC();

	/** 自动寻路的目标位置（鼠标点击时记录，自动寻路时作为终点） */
	FVector CachedDestination = FVector::ZeroVector;

	/** 鼠标按住时间（用于区分短按和长按） */
	float FollowTime = 0.f;

	/** 短按阈值（秒）：按住时间小于此值视为短按，触发点击移动 */
	float ShortPressThreshold = 0.5f;

	/** 是否正在自动寻路移动 */
	bool bAutoRunning = false;

	/** 当前鼠标目标状态（影响点击行为） */
	ETargetingStatus TargetingStatus = ETargetingStatus::NotTargeting;

	/**
	 * 自动寻路到达判定半径（单位：cm）
	 * 角色与目标点距离小于此值时停止自动寻路
	 */
	UPROPERTY(EditDefaultsOnly)
	float AutoRunAcceptanceRadius = 50.f;

	/**
	 * 自动寻路路径样条线
	 * 使用 Navigation Mesh 生成路径后，将路径点存储在此样条线中
	 * 每帧沿样条线方向移动角色
	 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<USplineComponent> Spline;

	/** 点击地面时在目标位置播放的 Niagara 特效（点击反馈） */
	UPROPERTY(EditDefaultsOnly)
	TObjectPtr<UNiagaraSystem> ClickNiagaraSystem;

	/**
	 * 执行自动寻路移动
	 * 每帧计算样条线上最近点的切线方向，并向该方向移动角色
	 */
	void AutoRun();

	/** 浮动伤害数字 Widget 组件类（在 Details 面板中指定） */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<UDamageTextComponent> DamageTextComponentClass;

	/** 魔法圆圈 Actor 类（在 Details 面板中指定） */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<AMagicCircle> MagicCircleClass;

	/** 当前场景中的魔法圆圈 Actor 实例（ShowMagicCircle 时生成，HideMagicCircle 时销毁） */
	UPROPERTY()
	TObjectPtr<AMagicCircle> MagicCircle;

	/** 每帧更新魔法圆圈位置（跟随鼠标光标在地面的投影位置） */
	void UpdateMagicCircleLocation();
};

// Copyright Druid Mechanics


#include "AI/BTService_FindNearestPlayer.h"
#include "AIController.h"
#include "BehaviorTree/BTFunctionLibrary.h"
#include "Kismet/GameplayStatics.h"

/**
 * 每帧更新节点（BTService 的核心函数）
 * 
 * 实现流程：
 * 1. 调用父类 TickNode
 * 2. 获取 AI 控制的 Pawn
 * 3. 确定目标标签：
 *    - 如果 Pawn 是 Player，目标标签为 "Enemy"
 *    - 否则目标标签为 "Player"
 * 4. 获取所有带有目标标签的 Actor
 * 5. 遍历所有 Actor，找到距离最近的：
 *    - 计算距离（GetDistanceTo）
 *    - 更新最近距离和最近 Actor
 * 6. 将最近 Actor 设置到黑板（TargetToFollowSelector）
 * 7. 将最近距离设置到黑板（DistanceToTargetSelector）
 * 
 * @param OwnerComp 行为树组件
 * @param NodeMemory 节点内存
 * @param DeltaSeconds 帧时间间隔
 * 
 * 使用场景：
 * - AI 行为树每帧调用，更新目标信息
 * 
 * 注意：
 * - 此服务会持续更新最近目标，确保 AI 始终追踪最近的敌人/玩家
 * - 如果未找到目标，黑板值会被设置为 nullptr 和最大浮点数
 */
void UBTService_FindNearestPlayer::TickNode(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory, float DeltaSeconds)
{
	Super::TickNode(OwnerComp, NodeMemory, DeltaSeconds);

	APawn* OwningPawn = AIOwner->GetPawn();

	// 确定目标标签（Player 找 Enemy，Enemy 找 Player）
	const FName TargetTag = OwningPawn->ActorHasTag(FName("Player")) ? FName("Enemy") : FName("Player");

	// 获取所有带有目标标签的 Actor
	TArray<AActor*> ActorsWithTag;
	UGameplayStatics::GetAllActorsWithTag(OwningPawn, TargetTag, ActorsWithTag);

	// 找到距离最近的 Actor
	float ClosestDistance = TNumericLimits<float>::Max();
	AActor* ClosestActor = nullptr;
	for (AActor* Actor : ActorsWithTag)
	{
		if (IsValid(Actor) && IsValid(OwningPawn))
		{
			const float Distance = OwningPawn->GetDistanceTo(Actor);
			if (Distance < ClosestDistance)
			{
				ClosestDistance = Distance;
				ClosestActor = Actor;
			}
		}
	}

	// 更新黑板值
	UBTFunctionLibrary::SetBlackboardValueAsObject(this,TargetToFollowSelector, ClosestActor);
	UBTFunctionLibrary::SetBlackboardValueAsFloat(this, DistanceToTargetSelector, ClosestDistance);
}

// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "MagicCircle.generated.h"

/**
 * 魔法圆圈 Actor
 *
 * 在地面显示的技能目标指示器，用于需要指定目标位置的技能
 * 跟随鼠标光标在地面的投影位置移动
 *
 * 功能：
 * - 使用 DecalComponent 在地面投影圆圈贴花
 * - 支持自定义贴花材质（不同技能可以有不同的圆圈外观）
 * - 由 AAuraPlayerController 管理生命周期（ShowMagicCircle/HideMagicCircle）
 * - 每帧跟随鼠标光标位置更新（在 PlayerController 的 UpdateMagicCircleLocation 中）
 *
 * 使用方式：
 *   // 在 PlayerController 中
 *   MagicCircle = GetWorld()->SpawnActor<AMagicCircle>(MagicCircleClass);
 *   MagicCircle->MagicCircleDecal->SetMaterial(0, DecalMaterial);
 *   // 每帧更新位置
 *   MagicCircle->SetActorLocation(CursorHitLocation);
 */
UCLASS()
class AURA_API AMagicCircle : public AActor
{
	GENERATED_BODY()

public:	
	AMagicCircle();
	virtual void Tick(float DeltaTime) override;

	/**
	 * 魔法圆圈贴花组件
	 * 在地面投影圆圈图案，支持自定义材质
	 * 蓝图可读写，允许在运行时修改贴花材质
	 */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly)
	TObjectPtr<UDecalComponent> MagicCircleDecal;

protected:
	virtual void BeginPlay() override;
};

