#pragma once

#include "CoreMinimal.h"
#include "UObject/Interface.h"
#include "EnemyInterface.generated.h"

/** UInterface 声明（不需要修改） */
UINTERFACE(MinimalAPI)
class UEnemyInterface : public UInterface
