public:
	FString GetActorNameOrLabel() const
	{
#if WITH_EDITORONLY_DATA || ACTOR_HAS_LABELS
		if (!ActorLabel.IsEmpty())
		{
			return ActorLabel;
		}
#endif
		return GetName();
	}

	FStringView GetActorLabelView() const
	{
#if WITH_EDITORONLY_DATA || ACTOR_HAS_LABELS
		return ActorLabel;
#else
		return FStringView();
#endif
	}

